-- Fee schemes and concessions (docs/designs/fee-schemes, Stage 4 F5, WF5): dated schemes with rules per fee type, made by one
-- person and approved by another (the database checks both); one scheme per registration, assigned before anything is paid;
-- concessions stamped by the database reduce owed in fee_due_balance. Head generated by prisma migrate diff.
-- CreateTable
CREATE TABLE "app"."fee_scheme" (
    "id" SERIAL NOT NULL,
    "code" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "valid_from" DATE NOT NULL,
    "valid_to" DATE NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'DRAFT',
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "created_by" UUID NOT NULL,
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_by" UUID NOT NULL,
    "approved_at" TIMESTAMPTZ,
    "approved_by" UUID,
    "retired_at" TIMESTAMPTZ,
    "retired_by" UUID,
    "retired_reason" TEXT,

    CONSTRAINT "fee_scheme_pkey" PRIMARY KEY ("id")
);

