    "scheme_id" INTEGER NOT NULL,
    "fee_type_id" INTEGER NOT NULL,
    "kind" TEXT NOT NULL,
    "value" DECIMAL(14,2) NOT NULL,

    CONSTRAINT "fee_scheme_rule_pkey" PRIMARY KEY ("scheme_id","fee_type_id")
);

