-- ---------- Named checks (mirrored in src/server/schemes.ts) ----------
alter table app.fee_scheme add constraint fee_scheme_code_check check (code ~ '^[!-~]+( [!-~]+)*$' and code = upper(code) and length(code) <= 30);
alter table app.fee_scheme add constraint fee_scheme_name_check check (name = btrim(name) and char_length(name) between 1 and 200);
alter table app.fee_scheme add constraint fee_scheme_valid_check check (valid_to >= valid_from);
alter table app.fee_scheme add constraint fee_scheme_status_check check (status in ('DRAFT', 'LIVE', 'RETIRED'));
alter table app.fee_scheme add constraint fee_scheme_approved_check check ((status <> 'DRAFT') = (approved_at is not null and approved_by is not null));
alter table app.fee_scheme add constraint fee_scheme_retired_check check ((status = 'RETIRED') = (retired_at is not null and retired_by is not null and retired_reason is not null));
alter table app.fee_scheme add constraint fee_scheme_reason_check check (retired_reason is null or (retired_reason = btrim(retired_reason) and char_length(retired_reason) between 1 and 500));
alter table app.fee_scheme_rule add constraint fee_scheme_rule_kind_check check (kind in ('PERCENT', 'AMOUNT'));
alter table app.fee_scheme_rule add constraint fee_scheme_rule_value_check check (case when kind = 'PERCENT' then value between 0.01 and 100 else value > 0 end);
alter table app.fee_concession add constraint fee_concession_amount_check check (amount > 0);

-- ---------- Scheme guard: maker and checker in the database (DD-1). Rules and permissions, so they bind every role; a missing
-- permission is 42501 (Forbidden, audited DENIED). Each refusal names its own constraint (Z8-2, R4). ----------
create function app.fee_scheme_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare me uuid := app.session_user_id();
begin
  if tg_op = 'INSERT' then
    if not app.has_permission('scheme.manage', null) then
      raise exception 'scheme.manage is required' using errcode = '42501';
    end if;
    new.status := 'DRAFT'; new.approved_at := null; new.approved_by := null;
    new.retired_at := null; new.retired_by := null; new.retired_reason := null;
    new.created_at := now(); new.created_by := coalesce(me, new.created_by);
    new.updated_at := new.created_at; new.updated_by := new.created_by;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.status <> 'DRAFT' then
      raise exception 'a live or retired scheme never changes: constraint "fee_scheme_guard"' using errcode = '23514', constraint = 'fee_scheme_guard';
    end if;
    if not app.has_permission('scheme.manage', null) then
      raise exception 'scheme.manage is required' using errcode = '42501';
    end if;
    return old;
  end if;
  -- a draft edit: name and validity only; every edit is stamped, so its editor cannot approve it (D4, R2)
  if old.status = 'DRAFT' and new.status = 'DRAFT' then
    if not app.has_permission('scheme.manage', null) then
      raise exception 'scheme.manage is required' using errcode = '42501';
    end if;
    if (to_jsonb(new) - 'name' - 'valid_from' - 'valid_to' - 'updated_at' - 'updated_by') is distinct from (to_jsonb(old) - 'name' - 'valid_from' - 'valid_to' - 'updated_at' - 'updated_by') then
      raise exception 'only the name and validity of a draft change: constraint "fee_scheme_guard"' using errcode = '23514', constraint = 'fee_scheme_guard';
    end if;
    new.updated_at := now(); new.updated_by := coalesce(me, new.updated_by);
    return new;
  end if;
  if old.status = 'DRAFT' and new.status = 'LIVE' then
    if not app.has_permission('scheme.approve', null) then
      raise exception 'scheme.approve is required' using errcode = '42501';
    end if;
    if not app.session_step_up_fresh(300) then
      raise exception 'approval needs a fresh step-up: constraint "fee_scheme_stepup_guard"' using errcode = '23514', constraint = 'fee_scheme_stepup_guard';
    end if;
    if (to_jsonb(new) - 'status' - 'approved_at' - 'approved_by') is distinct from (to_jsonb(old) - 'status' - 'approved_at' - 'approved_by') then
      raise exception 'approval changes nothing else: constraint "fee_scheme_guard"' using errcode = '23514', constraint = 'fee_scheme_guard';
    end if;
    if me is null or me = old.created_by or me = old.updated_by then
      raise exception 'the maker or last editor cannot approve: constraint "fee_scheme_self_guard"' using errcode = '23514', constraint = 'fee_scheme_self_guard';
    end if;
    if not exists (select 1 from app.fee_scheme_rule r where r.scheme_id = old.id) or not exists (select 1 from app.fee_scheme_course c where c.scheme_id = old.id) then
      raise exception 'a scheme needs a rule and a course: constraint "fee_scheme_incomplete_guard"' using errcode = '23514', constraint = 'fee_scheme_incomplete_guard';
    end if;
    if old.valid_to < (now() at time zone 'Asia/Kolkata')::date then
      raise exception 'the scheme has expired: constraint "fee_scheme_expired_guard"' using errcode = '23514', constraint = 'fee_scheme_expired_guard';
    end if;
    new.approved_at := now(); new.approved_by := me;
    return new;
  end if;
  if old.status = 'LIVE' and new.status = 'RETIRED' then
    if not app.has_permission('scheme.approve', null) then
      raise exception 'scheme.approve is required' using errcode = '42501';
    end if;
    if not app.session_step_up_fresh(300) then
      raise exception 'retirement needs a fresh step-up: constraint "fee_scheme_stepup_guard"' using errcode = '23514', constraint = 'fee_scheme_stepup_guard';
    end if;
    if (to_jsonb(new) - 'status' - 'retired_at' - 'retired_by' - 'retired_reason') is distinct from (to_jsonb(old) - 'status' - 'retired_at' - 'retired_by' - 'retired_reason') then
      raise exception 'retirement changes nothing else: constraint "fee_scheme_guard"' using errcode = '23514', constraint = 'fee_scheme_guard';
    end if;
    new.retired_at := now(); new.retired_by := coalesce(me, new.retired_by);
    return new;
  end if;
  raise exception 'a live or retired scheme never changes: constraint "fee_scheme_guard"' using errcode = '23514', constraint = 'fee_scheme_guard';
end $$;
create trigger fee_scheme_guard before insert or update or delete on app.fee_scheme for each row execute function app.fee_scheme_guard();

-- ---------- Parts change only on a draft, and each change stamps the scheme's editor through fee_scheme_guard (Z8-1, R2) ----------
create function app.fee_scheme_part_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare sid int := case when tg_op = 'DELETE' then old.scheme_id else new.scheme_id end; st text;
begin
  if not app.has_permission('scheme.manage', null) then
    raise exception 'scheme.manage is required' using errcode = '42501';
  end if;
  select s.status into st from app.fee_scheme s where s.id = sid for update;
  if st is distinct from 'DRAFT' then
    raise exception 'only a draft scheme''s rules and targets change: constraint "fee_scheme_part_guard"' using errcode = '23514', constraint = 'fee_scheme_part_guard';
  end if;
  update app.fee_scheme set name = name where id = sid;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end $$;
create trigger fee_scheme_part_guard before insert or update or delete on app.fee_scheme_rule for each row execute function app.fee_scheme_part_guard();
create trigger fee_scheme_part_guard before insert or update or delete on app.fee_scheme_course for each row execute function app.fee_scheme_part_guard();
create trigger fee_scheme_part_guard before insert or update or delete on app.fee_scheme_centre for each row execute function app.fee_scheme_part_guard();

-- Row lock on a scheme for assignment, so a retirement waits for it (D9). A direct "for share" would be filtered by the
-- scheme's UPDATE policy for everyone without a scheme permission (R1; the 0009 ticket_type_lock trap). Locks take a volatile function.
create function app.fee_scheme_lock(p_id int) returns table (status text, valid_from date, valid_to date)
language sql volatile security definer
set search_path = pg_catalog, app
as $$
  select s.status, s.valid_from, s.valid_to from app.fee_scheme s where s.id = p_id for share
$$;
revoke all on function app.fee_scheme_lock(int) from public;
grant execute on function app.fee_scheme_lock(int) to gems_app;

-- ---------- Assignment guard: under the fee-dues lock; the id is the app's (R6), who and when are stamped ----------
create function app.fee_scheme_assignment_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare r_status text; r_centre int; r_course int; r_on date; s_status text; s_from date; s_to date;
begin
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || new.registration_id::text));
  new.created_at := now();
  new.created_by := coalesce(app.session_user_id(), new.created_by);
  select g.status::text, g.centre_id, co.id, a.admitted_on into r_status, r_centre, r_course, r_on
    from app.registration g join app.admission a on a.id = g.admission_id join app.course co on co.code = g.course_code
    where g.id = new.registration_id;
  if r_status is distinct from 'ACTIVE' or r_centre is distinct from new.centre_id then
    raise exception 'the registration is not active at that centre: constraint "fee_scheme_registration_guard"' using errcode = '23514', constraint = 'fee_scheme_registration_guard';
  end if;
  select l.status, l.valid_from, l.valid_to into s_status, s_from, s_to from app.fee_scheme_lock(new.scheme_id) l;
  if s_status is distinct from 'LIVE' or r_on < s_from or r_on > s_to then
    raise exception 'the scheme is not live on the admission date: constraint "fee_scheme_target_guard"' using errcode = '23514', constraint = 'fee_scheme_target_guard';
  end if;
  if not exists (select 1 from app.fee_scheme_course c where c.scheme_id = new.scheme_id and c.course_id = r_course) then
    raise exception 'the scheme does not target this course: constraint "fee_scheme_target_guard"' using errcode = '23514', constraint = 'fee_scheme_target_guard';
  end if;
  if exists (select 1 from app.fee_scheme_centre c where c.scheme_id = new.scheme_id) then
    if not exists (select 1 from app.fee_scheme_centre c where c.scheme_id = new.scheme_id and c.centre_id = new.centre_id) then
      raise exception 'the scheme does not target this centre: constraint "fee_scheme_target_guard"' using errcode = '23514', constraint = 'fee_scheme_target_guard';
    end if;
  end if;
  -- one rule for "paid" (Z8-5): nothing paid on any plan due of the registration
  if exists (select 1 from app.fee_due d join app.fee_due_balance b on b.due_id = d.id
             where d.registration_id = new.registration_id and d.source = 'PLAN' and b.paid > 0) then
    raise exception 'something is already paid: constraint "fee_scheme_paid_guard"' using errcode = '23514', constraint = 'fee_scheme_paid_guard';
  end if;
  return new;
end $$;
create trigger fee_scheme_assignment_guard before insert on app.fee_scheme_assignment for each row execute function app.fee_scheme_assignment_guard();

-- At commit the assignment has given something (DD-8)
create function app.fee_scheme_assignment_given() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
begin
  if not exists (select 1 from app.fee_concession c where c.assignment_id = new.id) then
    raise exception 'the scheme gives nothing here: constraint "fee_scheme_given_guard"' using errcode = '23514', constraint = 'fee_scheme_given_guard';
  end if;
  return null;
end $$;
create constraint trigger fee_scheme_assignment_given after insert on app.fee_scheme_assignment
  deferrable initially deferred for each row execute function app.fee_scheme_assignment_given();

-- ---------- Concession guard: stamps the amount (D7), only in the assignment's own transaction (D5), under the lock (C3);
-- a zero share is skipped (returns NULL), so the app inserts every ruled due without computing anything ----------
create function app.fee_concession_guard() returns trigger
language plpgsql security invoker set search_path = pg_catalog, app
as $$
declare a_reg uuid; a_centre int; a_scheme int; a_at timestamptz;
  d_reg uuid; d_centre int; d_source text; d_type int; d_gross numeric; d_on date; k text; v numeric; later numeric;
begin
  select s.registration_id, s.centre_id, s.scheme_id, s.created_at into a_reg, a_centre, a_scheme, a_at
    from app.fee_scheme_assignment s where s.id = new.assignment_id;
  if not found then
    raise exception 'the assignment is not found: constraint "fee_concession_guard"' using errcode = '23514', constraint = 'fee_concession_guard';
  end if;
  perform pg_advisory_xact_lock(hashtext('fee-dues:' || a_reg::text));
  if a_at is distinct from now() then
    raise exception 'concessions are given only with their assignment: constraint "fee_concession_guard"' using errcode = '23514', constraint = 'fee_concession_guard';
  end if;
  select d.registration_id, d.centre_id, d.source, d.fee_type_id, d.gross, d.due_on into d_reg, d_centre, d_source, d_type, d_gross, d_on
    from app.fee_due d where d.id = new.due_id;
  if d_reg is distinct from a_reg or d_centre is distinct from a_centre or d_source is distinct from 'PLAN' or new.centre_id is distinct from a_centre then
    raise exception 'a concession is on a plan due of its registration: constraint "fee_concession_guard"' using errcode = '23514', constraint = 'fee_concession_guard';
  end if;
  select r.kind, r.value into k, v from app.fee_scheme_rule r where r.scheme_id = a_scheme and r.fee_type_id = d_type;
  if not found then
    raise exception 'the scheme has no rule for this fee type: constraint "fee_concession_guard"' using errcode = '23514', constraint = 'fee_concession_guard';
  end if;
  if k = 'PERCENT' then
    new.amount := round(d_gross * v / 100, 2);
  else
    -- AMOUNT is a total per fee type, taken from the latest dues first (DD-2, Z8-6)
    select coalesce(sum(o.gross), 0) into later from app.fee_due o
      where o.registration_id = d_reg and o.source = 'PLAN' and o.fee_type_id = d_type and (o.due_on, o.id) > (d_on, new.due_id);
    new.amount := least(d_gross, greatest(0, v - later));
  end if;
  new.created_at := now();
  if new.amount = 0 then return null; end if;
  return new;
end $$;
create trigger fee_concession_guard before insert on app.fee_concession for each row execute function app.fee_concession_guard();
create trigger fee_scheme_assignment_no_update_delete before update or delete on app.fee_scheme_assignment for each row execute function app.ticket_immutable();
create trigger fee_scheme_assignment_no_truncate before truncate on app.fee_scheme_assignment for each statement execute function app.ticket_immutable();
create trigger fee_concession_no_update_delete before update or delete on app.fee_concession for each row execute function app.ticket_immutable();
create trigger fee_concession_no_truncate before truncate on app.fee_concession for each statement execute function app.ticket_immutable();

-- ---------- Owed counts concessions, defined once (G3, C2, D10, R10): the 0031 view plus concession, added last ----------
create or replace view app.fee_due_balance with (security_invoker = true) as
  select x.due_id, x.registration_id, x.paid, x.outstanding, x.owed,
    coalesce(x.held, false) as held,
    (case when coalesce(x.held, false) then 0 else x.owed end)::numeric(14,2) as collectable,
    x.concession
  from (
    select d.id as due_id, d.registration_id,
      coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0)::numeric(14,2) as paid,
      (d.gross - c.amount - coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0))::numeric(14,2) as outstanding,
      (case when d.source = 'PLAN' then d.gross - c.amount - coalesce(sum(a.amount) filter (where r.status = 'ACTIVE'), 0) else 0 end)::numeric(14,2) as owed,
      (h.action = 'HOLD') as held,
      c.amount as concession
    from app.fee_due d
      left join app.receipt_allocation a on a.due_id = d.id
      left join app.receipt r on r.id = a.receipt_id
      left join lateral (select e.action from app.fee_hold_event e where e.due_id = d.id order by e.id desc limit 1) h on true
      cross join lateral (select coalesce(sum(f.amount), 0)::numeric(14,2) as amount from app.fee_concession f where f.due_id = d.id) c
    group by d.id, h.action, c.amount) x;

-- ---------- RLS: live schemes for everyone, drafts for scheme holders (Z8-7); concessions read like receipts (student.view) ----------
alter table app.fee_scheme enable row level security;
alter table app.fee_scheme force row level security;
create policy fee_scheme_select on app.fee_scheme for select using (status <> 'DRAFT' or (select app.has_permission('scheme.manage', null)) or (select app.has_permission('scheme.approve', null)));
create policy fee_scheme_insert on app.fee_scheme for insert with check ((select app.has_permission('scheme.manage', null)));
create policy fee_scheme_update on app.fee_scheme for update using ((select app.has_permission('scheme.manage', null)) or (select app.has_permission('scheme.approve', null)))
  with check ((select app.has_permission('scheme.manage', null)) or (select app.has_permission('scheme.approve', null)));
create policy fee_scheme_delete on app.fee_scheme for delete using ((select app.has_permission('scheme.manage', null)));
do $$
declare t text;
begin
  foreach t in array array['fee_scheme_rule', 'fee_scheme_course', 'fee_scheme_centre'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy %I on app.%I for select using (true)', t || '_select', t);
    execute format('create policy %I on app.%I for insert with check ((select app.has_permission(''scheme.manage'', null)))', t || '_insert', t);
    execute format('create policy %I on app.%I for update using ((select app.has_permission(''scheme.manage'', null))) with check ((select app.has_permission(''scheme.manage'', null)))', t || '_update', t);
    execute format('create policy %I on app.%I for delete using ((select app.has_permission(''scheme.manage'', null)))', t || '_delete', t);
  end loop;
  foreach t in array array['fee_scheme_assignment', 'fee_concession'] loop
    execute format('alter table app.%I enable row level security', t);
    execute format('alter table app.%I force row level security', t);
    execute format('create policy %I on app.%I for select using (centre_id = any ((select app.scoped_centre_ids(''student.view''))::int[]))', t || '_select', t);
    execute format('create policy %I on app.%I for insert with check (centre_id = any ((select app.scoped_centre_ids(''fee.concession''))::int[]))', t || '_insert', t);
    execute format('create policy %I on app.%I for update using (false)', t || '_update', t);
    execute format('create policy %I on app.%I for delete using (false)', t || '_delete', t);
  end loop;
end $$;

-- ---------- Permissions; the system administrator holds every permission (0013) ----------
insert into app.permission (key, description, sensitive) values
  ('scheme.manage', 'Create and edit fee schemes', true),
  ('scheme.approve', 'Approve or retire fee schemes', true),
  ('fee.concession', 'Assign a fee scheme to a learner', false)
on conflict (key) do nothing;
insert into app.role_permission (role_id, permission_key) select r.id, p.k from app.role r, unnest(array['scheme.manage', 'scheme.approve', 'fee.concession']) p(k)
where r.key = 'system_admin' on conflict do nothing;

-- ---------- Grants: status changes only through the guard; ids of assignments are the app's, amounts the guard's ----------
grant select, insert (id, code, name, valid_from, valid_to), update (name, valid_from, valid_to, status, retired_reason), delete on app.fee_scheme to gems_app;
grant select, insert (scheme_id, fee_type_id, kind, value), update (kind, value), delete on app.fee_scheme_rule to gems_app;
grant select, insert, delete on app.fee_scheme_course, app.fee_scheme_centre to gems_app;
grant select, insert (id, registration_id, centre_id, scheme_id) on app.fee_scheme_assignment to gems_app;
grant select, insert (assignment_id, due_id, centre_id) on app.fee_concession to gems_app;
grant usage on sequence app.fee_scheme_id_seq, app.fee_scheme_assignment_id_seq, app.fee_concession_id_seq to gems_app;
